import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
export function showElectro(kind,t=null,reveal=false){const solid=t?.state==='solid',molten=kind==='molten',positive=t?.cation||'＋',negative=t?.anion||'−';const txt=(x,y,s,size=13,colour='#f8f6f2')=>`<text x="${x}" y="${y}" fill="${colour}" text-anchor="middle" font-family="sans-serif" font-size="${size}">${s}</text>`;const ion=(x,y,s,c)=>`<circle cx="${x}" cy="${y}" r="23" fill="${c}" stroke="#d4dfe7" stroke-opacity=".5"/>${txt(x,y+5,s,13,'#182e44')}`;renderDiagram(molten?'Two electrodes. Two products.':'Charge needs mobile carriers',molten?t?.name||'Molten binary ionic compound':t?.name||'Molten or aqueous electrolyte',`<svg class="lab-svg" viewBox="0 0 440 260" role="img" aria-label="${solid?'Solid: ions fixed in place':'Mobile positive ions move to negative cathode; negative ions to positive anode'}. Inert electrodes and external direct-current supply."><defs><linearGradient id="cellFill" x2="0" y2="1"><stop stop-color="#304b61"/><stop offset="1" stop-color="#182e44"/></linearGradient><marker id="ionArrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#d4dfe7"/></marker></defs><path d="M55 70 V225 H385 V70" fill="url(#cellFill)" stroke="#b7c8d6" stroke-width="2"/><path d="M85 55 V160 M355 55 V160" stroke="#d4dfe7" stroke-width="13"/>${txt(85,28,'− Cathode')}${txt(355,28,'+ Anode')}${txt(220,56,'DC supply',11)}${ion(160,120,positive,'#ed8b78')}${ion(280,175,negative,'#b7c8d6')}${solid?txt(220,210,'Fixed ions: no current'): '<path d="M130 120 H99 M310 175 H342" stroke="#d4dfe7" stroke-width="2" marker-end="url(#ionArrow)"/>'}${txt(220,247,reveal&&molten?`${t.metal} at cathode · ${t.nonmetal.replace('2','₂')} at anode`:'Predict before revealing products',12)}</svg><p class="diagram-caption">Symbolic: ion sizes, numbers and paths are illustrative. Electrons move in wires; ions in electrolyte.</p>`,'INERT ELECTRODES · SYMBOLIC MODEL');}
